PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS organizations(id INTEGER PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS units(id INTEGER PRIMARY KEY,org INTEGER NOT NULL REFERENCES organizations(id),name TEXT NOT NULL,settings TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS config_versions(id INTEGER PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,version INTEGER NOT NULL,settings TEXT NOT NULL,created TEXT NOT NULL,UNIQUE(unit,version));
CREATE TABLE IF NOT EXISTS rooms(id INTEGER PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL REFERENCES units(id),name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS people(id INTEGER PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL REFERENCES units(id),name TEXT NOT NULL,kind TEXT NOT NULL,profession TEXT,registry TEXT,cpf TEXT,phone TEXT,registration TEXT,plan_until TEXT,tutor INTEGER REFERENCES people(id),active INTEGER NOT NULL DEFAULT 1,UNIQUE(unit,registry),UNIQUE(unit,cpf));
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,person INTEGER REFERENCES people(id),login TEXT NOT NULL,role TEXT NOT NULL,password TEXT,generation INTEGER NOT NULL DEFAULT 0,UNIQUE(org,login));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user INTEGER NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires TEXT NOT NULL,temporary INTEGER NOT NULL,generation INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reservations(id INTEGER PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,room INTEGER NOT NULL REFERENCES rooms(id),person INTEGER NOT NULL REFERENCES people(id),student INTEGER REFERENCES people(id),tutor INTEGER REFERENCES people(id),category TEXT NOT NULL,start TEXT NOT NULL,end TEXT NOT NULL,status TEXT NOT NULL,payment TEXT NOT NULL,presence TEXT NOT NULL DEFAULT 'pendente',whatsapp INTEGER NOT NULL DEFAULT 0,training INTEGER NOT NULL DEFAULT 0,used INTEGER NOT NULL DEFAULT 0,snapshot TEXT NOT NULL,expires TEXT,created TEXT NOT NULL,operator INTEGER NOT NULL,relocated INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS reservation_interval ON reservations(unit,start,end);
CREATE TABLE IF NOT EXISTS benefits(org INTEGER NOT NULL,unit INTEGER NOT NULL,cpf TEXT NOT NULL,month TEXT NOT NULL,reservation INTEGER NOT NULL REFERENCES reservations(id),PRIMARY KEY(org,unit,cpf,month));
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,reservation INTEGER NOT NULL UNIQUE REFERENCES reservations(id),amount INTEGER NOT NULL,reference TEXT NOT NULL,created TEXT NOT NULL,operator INTEGER NOT NULL,UNIQUE(org,unit,reference));
CREATE TABLE IF NOT EXISTS refunds(id INTEGER PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,reservation INTEGER NOT NULL UNIQUE REFERENCES reservations(id),amount INTEGER NOT NULL,retained INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pendente',reference TEXT,created TEXT NOT NULL,operator INTEGER);
CREATE TABLE IF NOT EXISTS penalties(id INTEGER PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,identity TEXT NOT NULL,reservation INTEGER NOT NULL UNIQUE,start TEXT NOT NULL,end TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS blocks(id INTEGER PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,room INTEGER,person INTEGER,start TEXT NOT NULL,end TEXT NOT NULL,reason TEXT NOT NULL,operator INTEGER NOT NULL,origin TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS work(id INTEGER PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,person INTEGER NOT NULL REFERENCES people(id),weekday INTEGER NOT NULL,start TEXT NOT NULL,end TEXT NOT NULL,valid_from TEXT NOT NULL,valid_to TEXT NOT NULL,contract_minutes INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS schedules(id INTEGER PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL,month TEXT NOT NULL,anchor TEXT NOT NULL,assignments TEXT NOT NULL,errors TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS swaps(id INTEGER PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,schedule INTEGER NOT NULL,version INTEGER NOT NULL,source INTEGER NOT NULL,target INTEGER NOT NULL,assignment INTEGER NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reasons(id INTEGER PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,title TEXT NOT NULL,requires_detail INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,actor INTEGER,action TEXT NOT NULL,entity TEXT NOT NULL,data TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,message TEXT NOT NULL,created TEXT NOT NULL);
